# WAR ARENA - HTTP/API Layer - Installer
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-api.ps1
# Additive only. Zero new dependencies (built on node:http). Files Base64-encoded.
$ErrorActionPreference = "Stop"
Write-Host "WAR - HTTP/API installer" -ForegroundColor Cyan
function Write-B64([string]$Path, [string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path, [System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/api/app.ts" ""
Write-B64 "src/api/handlers.ts" ""
Write-B64 "src/api/httpResult.ts" ""
Write-B64 "src/api/httpServer.ts" ""
Write-B64 "src/api/index.ts" ""
Write-B64 "src/api/router.ts" ""
Write-B64 "tests/architecture/apiBoundaries.test.ts" ""
Write-B64 "tests/unit/api.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "root typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "HTTP/API layer installed." -ForegroundColor Green
Write-Host "Expected: 830 passed + 1 skipped, 392 guards. No new npm deps." -ForegroundColor Yellow
